() => {
  var params = this.getComponent('stock_movement_no');
  const { options } = params;
  return options?.dynamicRuleField;
}

item.validator:
const page_status = this.getValue("page_status");

if (page_status === "View" || !value) {
  callback();
  return;
}

let organizationId = this.getVarGlobal('deptParentId');
if(organizationId === '0'){
    organizationId = this.getVarSystem('deptIds').split(',')[0];
}


db.collection("Item")
  .where({ material_code: value, organization_id: organizationId })
  .get()
  .then((response) => {
    const matchingItems = response.data || [];

    if (matchingItems.length === 0) {
      callback();
      return;
    }

    if (page_status === "Edit") {
      const currentItemId = this.getValue("id");
      const isSameItem = matchingItems.some(
        (item) => item.id === currentItemId
      );
      callback(isSameItem ? undefined : "Item code already exists.");
    } else {
      callback("Item code already exists.");
    }
  })
  .catch((error) => {
    console.error("Error checking item:", error);
    callback("Error validating item code.");
  });

options.validator:
const data = this.getValues();
const stockMovement = data.stock_movement || [];
const rowIndex = data.sm_item_balance?.row_index;
// rule.field is "sm_item_balance.table_item_balance.<row>.sm_quantity", where
// <row> is the row's fm_key (e.g. "byh6k1cv") rather than a numeric index.
const rowKey = rule.field.split(".")[2];
const balanceRows = data.sm_item_balance?.table_item_balance || [];
const row =
  balanceRows.find((r) => r && r.fm_key === rowKey) || balanceRows[rowKey];
// The rule stays registered after the dialog closes and its rows are gone, and
// the main form's this.validate() runs it on every save. A missing row, or a
// row with nothing allocated, has nothing to check -- throwing here would
// reject the whole save (Draft included).
if (!row || !(parseFloat(value) > 0)) {
  callback();
  return;
}
const materialId = row.material_id;
const balanceId = row.balance_id;
const locationId = row.location_id;
const category = row.category;

const category_type = row.category ?? row.category_from;

const unrestricted_field = row.unrestricted_qty;
const reserved_field = row.reserved_qty;
const quality_field = row.qualityinsp_qty;
const blocked_field = row.block_qty;

let selectedField;

switch (category_type) {
  case "Unrestricted":
    selectedField = unrestricted_field;
    break;
  case "Reserved":
    selectedField = reserved_field;
    break;
  case "Quality Inspection":
    selectedField = quality_field;
    break;
  case "Blocked":
    selectedField = blocked_field;
    break;
  default:
    callback("Invalid category type");
    return;
}

// Sum already-confirmed allocations from OTHER stock_movement lines hitting the
// same balance/location/category, so cross-line over-allocation is caught.
let confirmedQuantity = 0;

for (let i = 0; i < stockMovement.length; i++) {
  if (i === rowIndex) continue;
  const item = stockMovement[i];
  if (
    item.item_selection !== materialId ||
    !item.total_quantity ||
    !item.temp_qty_data
  ) continue;

  let tempDataParsed;
  try {
    tempDataParsed = JSON.parse(item.temp_qty_data);
  } catch (e) {
    continue;
  }
  if (!Array.isArray(tempDataParsed)) continue;

  for (const tempItem of tempDataParsed) {
    if (
      tempItem.material_id === materialId &&
      tempItem.balance_id === balanceId &&
      tempItem.location_id === locationId &&
      tempItem.category === category &&
      tempItem.sm_quantity > 0
    ) {
      confirmedQuantity += tempItem.sm_quantity;
    }
  }
}

if (selectedField < value + confirmedQuantity) {
  callback(`Quantity in ${category_type} is not enough.`);
} else {
  callback();
}

