// this.validate() rejects with { "<field path>": { message } } (or arrays of
// { field, message }). Return the first message string found at any depth.
const findFieldMessage = (obj) => {
  if (!obj || typeof obj !== "object") return null;
  if (typeof obj.message === "string" && obj.message) return obj.message;

  const children = Array.isArray(obj) ? obj : Object.values(obj);
  for (const child of children) {
    const found = findFieldMessage(child);
    if (found) return found;
  }
  return null;
};

// Draft still validates the form, but these batch details are completion-only.
// The form engine validates hidden/disabled fields too, so filter only those
// three field errors and keep every other validation error intact.
const validateDraft = async () => {
  try {
    await this.validate();
  } catch (error) {
    if (!error || typeof error !== "object") throw error;

    const entries = Object.entries(error);
    if (entries.length === 0) throw error;

    const draftOptionalFields = [
      ".batch_number",
      ".manufacturing_date",
      ".expired_date",
    ];
    // sm_item_balance is the Select Stock dialog: it is not saved with the
    // document and onConfirm_Stock already checked its quantities.
    const remainingErrors = entries.filter(([field]) => {
      const isDraftQuantity =
        field.startsWith("item_display_table.") &&
        field.endsWith(".item_qty");

      return (
        !field.startsWith("sm_item_balance.") &&
        !isDraftQuantity &&
        !draftOptionalFields.some((suffix) => field.endsWith(suffix))
      );
    });

    // Nothing was filtered: this is not a batch-detail validation error.
    if (remainingErrors.length === entries.length) throw error;

    // Preserve all other form errors, if any.
    if (remainingErrors.length > 0) {
      throw Object.fromEntries(remainingErrors);
    }
  }
};

(async () => {
