(async function idaConfirmBatchAdd(payload) {
  const currentItemArray = payload?.itemArray || [];
  if (!currentItemArray.length) {
    this.$alert("Please select at least one item.", "Error", {
      confirmButtonText: "OK",
      type: "error",
    });
    return;
  }

  const getItemDefaultBin = (tableDefaultBin, plantId) => {
    if (!plantId || !Array.isArray(tableDefaultBin)) return null;
    const match = tableDefaultBin.find(
      (entry) => entry.plant_id === plantId && entry.bin_location,
    );
    return match
      ? {
          storageLocation: match.storage_location || "",
          binLocation: match.bin_location || "",
        }
      : null;
  };

  const loadPlantDefaults = async (plantId) => {
    if (!plantId) return { storageLocation: "", binLocation: "" };

    const storageResponse = await db
      .collection("storage_location")
      .where({
        plant_id: plantId,
        is_deleted: 0,
        is_default: 1,
        storage_status: 1,
        location_type: "Common",
      })
      .get()
      .catch(() => ({ data: [] }));
    const storageLocation = storageResponse.data?.[0]?.id || "";
    if (!storageLocation) return { storageLocation: "", binLocation: "" };

    const binResponse = await db
      .collection("bin_location")
      .where({
        plant_id: plantId,
        storage_location_id: storageLocation,
        is_deleted: 0,
        is_default: 1,
        bin_status: 1,
      })
      .get()
      .catch(() => ({ data: [] }));

    return {
      storageLocation,
      binLocation: binResponse.data?.[0]?.id || "",
    };
  };

  try {
    const allData = this.getValues();
    const existingLines = allData.stock_movement || [];
    const plantId = allData.issuing_operation_faci || "";
    const plantDefault = await loadPlantDefaults(plantId);

    const uomIds = [
      ...new Set(
        currentItemArray
          .flatMap((item) => [
            item.based_uom,
            ...(item.table_uom_conversion || []).map(
              (conversion) => conversion.alt_uom_id,
            ),
          ])
          .filter(Boolean),
      ),
    ];
    const uomRes = uomIds.length
      ? await db
          .collection("unit_of_measurement")
          .filter([
            {
              type: "branch",
              operator: "all",
              children: [
                { prop: "id", operator: "in", value: uomIds },
                { prop: "is_deleted", operator: "equal", value: 0 },
              ],
            },
          ])
          .get()
          .catch(() => ({ data: [] }))
      : { data: [] };
    const uomMap = new Map(
      (uomRes.data || []).map((uom) => [String(uom.id), uom]),
    );

    const newRows = currentItemArray.map((item, index) => {
      const itemDefault = getItemDefaultBin(item.table_default_bin, plantId);
      const storageLocation =
        itemDefault?.storageLocation || plantDefault.storageLocation;
      const binLocation =
        itemDefault?.binLocation || plantDefault.binLocation;
      const rowUoms = [
        item.based_uom,
        ...(item.table_uom_conversion || []).map(
          (conversion) => conversion.alt_uom_id,
        ),
      ]
        .filter(Boolean)
        .filter((id, position, values) => values.indexOf(id) === position)
        .map((id) => uomMap.get(String(id)))
        .filter(Boolean);

      let batchNumber = "-";
      if (item.item_batch_management === 1) {
        batchNumber =
          item.batch_number_genaration === "According To System Settings"
            ? "Auto-generated batch number"
            : "";
      }

      return {
        item_selection: item.id,
        item_name: item.material_name || "",
        item_desc: item.material_desc || "",
        requested_qty: 0,
        bom_ratio: null,
          quantity_uom: item.based_uom || "",
        uom_options: JSON.stringify(rowUoms),
        storage_location_id: storageLocation,
        location_id: binLocation,
        batch_number: batchNumber,
        manufacturing_date: "",
        expired_date: "",
        item_remark: "",
        item_remark_2: "",
        item_remark_3: "",
        project_id: allData.project_id || "",
        organization_id: allData.organization_id,
        issuing_plant: plantId,
        line_index: existingLines.length + index + 1,
      };
    });

    const storageIds = [
      ...new Set(newRows.map((row) => row.storage_location_id).filter(Boolean)),
    ];
    const binRes = storageIds.length
      ? await db
          .collection("bin_location")
          .filter([
            {
              type: "branch",
              operator: "all",
              children: [
                {
                  prop: "storage_location_id",
                  operator: "in",
                  value: storageIds,
                },
                { prop: "plant_id", operator: "equal", value: plantId },
                { prop: "is_deleted", operator: "equal", value: 0 },
                { prop: "bin_status", operator: "equal", value: 1 },
              ],
            },
          ])
          .get()
          .catch(() => ({ data: [] }))
      : { data: [] };

    const allRows = [...existingLines, ...newRows];
    await this.setData({ stock_movement: allRows });

    const batchFields = [
      "stock_movement.batch_number",
      "stock_movement.manufacturing_date",
      "stock_movement.expired_date",
    ];
    const hasBatchItem = allRows.some(
      (row) => row?.item_selection && row.batch_number !== "-",
    );
    if (hasBatchItem) this.display(batchFields);
    else this.hide(batchFields);

    newRows.forEach((row, index) => {
      const rowIndex = existingLines.length + index;
      let options = [];
      try {
        options = JSON.parse(row.uom_options || "[]");
      } catch (error) {
        options = [];
      }
      this.setOptionData(`stock_movement.${rowIndex}.quantity_uom`, options);
      this.setOptionData(
        `stock_movement.${rowIndex}.location_id`,
        (binRes.data || []).filter(
          (bin) => bin.storage_location_id === row.storage_location_id,
        ),
      );
      this.disabled(
        [
          `stock_movement.${rowIndex}.quantity_uom`,
          `stock_movement.${rowIndex}.storage_location_id`,
          `stock_movement.${rowIndex}.location_id`,
        ],
        false,
      );

      const isNoBatch = row.batch_number === "-";
      const isSystemGenerated =
        row.batch_number === "Auto-generated batch number";
      this.disabled(
        `stock_movement.${rowIndex}.batch_number`,
        isNoBatch || isSystemGenerated,
      );
      this.disabled(
        [
          `stock_movement.${rowIndex}.manufacturing_date`,
          `stock_movement.${rowIndex}.expired_date`,
        ],
        isNoBatch,
      );
    });

    this.closeDialog("dialog_item_selection");
  } catch (error) {
    console.error("Error adding recovery items:", error);
    this.$message.error(error.message || "Failed to add recovery items");
  }
}).call(this, arguments[0]);

(async function idaAfterUpdateItem(payload) {
  const rowIndex = payload?.rowIndex;
  if (rowIndex === undefined || rowIndex === null) return;

  // Deleting a row re-renders the table and fires this event for an index that
  // no longer exists. Writing `stock_movement.${rowIndex}.*` then would recreate
  // that row as a blank line, so only touch rows that are still in the table.
  const rowExists = () =>
    Boolean((this.getValue("stock_movement") || [])[rowIndex]);
  if (!rowExists()) return;

  const getItemDefaultBin = (tableDefaultBin, plantId) => {
    if (!plantId || !Array.isArray(tableDefaultBin)) return null;
    const match = tableDefaultBin.find(
      (entry) => entry.plant_id === plantId && entry.bin_location,
    );
    return match
      ? {
          storageLocation: match.storage_location || "",
          binLocation: match.bin_location || "",
        }
      : null;
  };

  const fetchUoms = async (itemData) => {
    const ids = [
      itemData.based_uom,
      ...(itemData.table_uom_conversion || []).map(
        (conversion) => conversion.alt_uom_id,
      ),
    ]
      .filter(Boolean)
      .filter((id, index, values) => values.indexOf(id) === index);
    if (!ids.length) return [];
    const response = await db
      .collection("unit_of_measurement")
      .filter([
        {
          type: "branch",
          operator: "all",
          children: [
            { prop: "id", operator: "in", value: ids },
            { prop: "is_deleted", operator: "equal", value: 0 },
          ],
        },
      ])
      .get()
      .catch(() => ({ data: [] }));
    return response.data || [];
  };

  const loadBins = async (storageLocationId, plantId) => {
    if (!storageLocationId || !plantId) return [];
    const response = await db
      .collection("bin_location")
      .where({
        storage_location_id: storageLocationId,
        plant_id: plantId,
        is_deleted: 0,
        bin_status: 1,
      })
      .get()
      .catch(() => ({ data: [] }));
    return response.data || [];
  };

  const loadPlantDefaults = async (plantId) => {
    if (!plantId) return { storageLocation: "", binLocation: "" };

    const storageResponse = await db
      .collection("storage_location")
      .where({
        plant_id: plantId,
        is_deleted: 0,
        is_default: 1,
        storage_status: 1,
        location_type: "Common",
      })
      .get()
      .catch(() => ({ data: [] }));
    const storageLocation = storageResponse.data?.[0]?.id || "";
    if (!storageLocation) return { storageLocation: "", binLocation: "" };

    const binResponse = await db
      .collection("bin_location")
      .where({
        plant_id: plantId,
        storage_location_id: storageLocation,
        is_deleted: 0,
        is_default: 1,
        bin_status: 1,
      })
      .get()
      .catch(() => ({ data: [] }));

    return {
      storageLocation,
      binLocation: binResponse.data?.[0]?.id || "",
    };
  };

  const refreshBatchFieldVisibility = () => {
    const rows = this.getValue("stock_movement") || [];
    const fields = [
      "stock_movement.batch_number",
      "stock_movement.manufacturing_date",
      "stock_movement.expired_date",
    ];
    const hasBatchItem = rows.some(
      (row) => row?.item_selection && row.batch_number !== "-",
    );
    if (hasBatchItem) this.display(fields);
    else this.hide(fields);
  };

  try {
    const value = payload?.value;
    const allData = this.getValues();

    if (!value) {
      await this.setData({
        [`stock_movement.${rowIndex}.requested_qty`]: 0,
        [`stock_movement.${rowIndex}.bom_ratio`]: null,
        [`stock_movement.${rowIndex}.total_quantity`]: 0,
        [`stock_movement.${rowIndex}.item_name`]: "",
        [`stock_movement.${rowIndex}.item_desc`]: "",
        [`stock_movement.${rowIndex}.quantity_uom`]: "",
        [`stock_movement.${rowIndex}.uom_options`]: "",
        [`stock_movement.${rowIndex}.storage_location_id`]: "",
        [`stock_movement.${rowIndex}.location_id`]: "",
        [`stock_movement.${rowIndex}.batch_number`]: "-",
        [`stock_movement.${rowIndex}.manufacturing_date`]: "",
        [`stock_movement.${rowIndex}.expired_date`]: "",
      });
      this.setOptionData(`stock_movement.${rowIndex}.quantity_uom`, []);
      this.setOptionData(`stock_movement.${rowIndex}.location_id`, []);
      this.disabled(
        [
          `stock_movement.${rowIndex}.location_id`,
          `stock_movement.${rowIndex}.batch_number`,
          `stock_movement.${rowIndex}.manufacturing_date`,
          `stock_movement.${rowIndex}.expired_date`,
        ],
        true,
      );
      refreshBatchFieldVisibility();
      return;
    }

    const itemData = payload?.fieldModel?.item;
    if (!itemData) {
      // A plain table re-render has no fieldModel. Restore each row's saved UOM
      // options without treating it as a new item selection.
      (allData.stock_movement || []).forEach((line, index) => {
        let options = [];
        try {
          options = JSON.parse(line.uom_options || "[]");
        } catch (error) {
          options = [];
        }
        this.setOptionData(`stock_movement.${index}.quantity_uom`, options);
      });
      refreshBatchFieldVisibility();
      return;
    }

    const plantId = allData.issuing_operation_faci || "";
    const plantDefault = await loadPlantDefaults(plantId);
    const itemDefault = getItemDefaultBin(itemData.table_default_bin, plantId);
    const storageLocation =
      itemDefault?.storageLocation || plantDefault.storageLocation;
    const binLocation =
      itemDefault?.binLocation || plantDefault.binLocation;
    const uomOptions = await fetchUoms(itemData);
    const bins = await loadBins(storageLocation, plantId);

    let batchNumber = "-";
    if (itemData.item_batch_management === 1) {
      batchNumber =
        itemData.batch_number_genaration === "According To System Settings"
          ? "Auto-generated batch number"
          : "";
    }

    // The row may have been deleted while the lookups above were running.
    if (!rowExists()) return;

    await this.setData({
      [`stock_movement.${rowIndex}.requested_qty`]: 0,
      [`stock_movement.${rowIndex}.bom_ratio`]: null,
      [`stock_movement.${rowIndex}.total_quantity`]: 0,
      [`stock_movement.${rowIndex}.item_name`]: itemData.material_name || "",
      [`stock_movement.${rowIndex}.item_desc`]: itemData.material_desc || "",
      [`stock_movement.${rowIndex}.quantity_uom`]: itemData.based_uom || "",
      [`stock_movement.${rowIndex}.uom_options`]: JSON.stringify(uomOptions),
      [`stock_movement.${rowIndex}.storage_location_id`]: storageLocation,
      [`stock_movement.${rowIndex}.location_id`]: binLocation,
      [`stock_movement.${rowIndex}.batch_number`]: batchNumber,
      [`stock_movement.${rowIndex}.manufacturing_date`]: "",
      [`stock_movement.${rowIndex}.expired_date`]: "",
      [`stock_movement.${rowIndex}.organization_id`]: allData.organization_id,
      [`stock_movement.${rowIndex}.issuing_plant`]: plantId,
      [`stock_movement.${rowIndex}.project_id`]: allData.project_id || "",
      [`stock_movement.${rowIndex}.line_index`]: rowIndex + 1,
    });

    refreshBatchFieldVisibility();

    this.setOptionData(`stock_movement.${rowIndex}.quantity_uom`, uomOptions);
    this.setOptionData(`stock_movement.${rowIndex}.location_id`, bins);
    this.disabled(
      [
        `stock_movement.${rowIndex}.storage_location_id`,
        `stock_movement.${rowIndex}.location_id`,
        `stock_movement.${rowIndex}.quantity_uom`,
      ],
      false,
    );

    const isNoBatch = batchNumber === "-";
    const isSystemGenerated = batchNumber === "Auto-generated batch number";
    this.disabled(
      `stock_movement.${rowIndex}.batch_number`,
      isNoBatch || isSystemGenerated,
    );
    this.disabled(
      [
        `stock_movement.${rowIndex}.manufacturing_date`,
        `stock_movement.${rowIndex}.expired_date`,
      ],
      isNoBatch,
    );
  } catch (error) {
    console.error("Error loading recovery item defaults:", error);
    this.$message.error(error.message || "Failed to load the recovery item");
  }
}).call(this, arguments[0]);

