(async () => {
  const rowIndex = arguments[0]?.rowIndex;
  if (rowIndex === undefined || rowIndex === null) return;

  const rows = this.getValue("stock_movement") || [];
  const row = rows[rowIndex];
  if (!row) return;

  // A null/blank ratio identifies a manually added recovery item. Its quantity
  // is independent of the header Disassembly Quantity.
  const isBomRow =
    row.bom_ratio !== null &&
    row.bom_ratio !== undefined &&
    row.bom_ratio !== "";
  if (!isBomRow) return;

  const disassemblyQty = parseFloat(this.getValue("item_qty")) || 0;
  if (disassemblyQty <= 0) return;

  const recoveryQty = parseFloat(arguments[0]?.value) || 0;
  const latestRatio = Number((recoveryQty / disassemblyQty).toFixed(8));
  await this.setData({
    [`stock_movement.${rowIndex}.bom_ratio`]: latestRatio,
  });
})();

(async function idaRecoveryStorageChanged(payload) {
  const rowIndex = payload?.rowIndex;
  if (rowIndex === undefined || rowIndex === null) return;

  // Deleting a row re-renders the table and fires this event for an index that
  // no longer exists. Writing `stock_movement.${rowIndex}.*` then would recreate
  // that row as a blank line, so only touch rows that are still in the table.
  const rowExists = () =>
    Boolean((this.getValue("stock_movement") || [])[rowIndex]);
  if (!rowExists()) return;

  try {
    const storageLocationId = payload?.value || "";
    const plantId = this.getValue("issuing_operation_faci") || "";
    if (!storageLocationId) {
      await this.setData({
        [`stock_movement.${rowIndex}.location_id`]: "",
      });
      this.setOptionData(`stock_movement.${rowIndex}.location_id`, []);
      this.disabled(`stock_movement.${rowIndex}.location_id`, true);
      return;
    }

    const response = await db
      .collection("bin_location")
      .where({
        storage_location_id: storageLocationId,
        plant_id: plantId,
        is_deleted: 0,
        bin_status: 1,
      })
      .get();
    const bins = response.data || [];
    const defaultBin = bins.find((bin) => bin.is_default === 1);

    // The row may have been deleted while the bin lookup was running.
    if (!rowExists()) return;

    this.setOptionData(`stock_movement.${rowIndex}.location_id`, bins);
    await this.setData({
      [`stock_movement.${rowIndex}.location_id`]: defaultBin?.id || "",
    });
    this.disabled(`stock_movement.${rowIndex}.location_id`, false);
  } catch (error) {
    console.error("Error loading recovery target locations:", error);
    this.$message.error(error.message || "Failed to load target locations");
  }
}).call(this, arguments[0]);

// idaV2_onClick_completed - Item Disassembly form, onClick of button_completed (one source for Completed and Complete & Post).
// IDA V2 (CONTRACT section 12): more than IDA_V2_MIN_MOVES moves, no handling unit, no serial pick -> IDA_V2_SUBMIT; anything
// else, a NOT_ELIGIBLE / INVALID answer or an error before SUBMIT -> the classic handler through triggerEvent, once.
const IDA_WF = {
  SUBMIT: "2112748971830149121", // IDA_V2_SUBMIT
  WORKER: "2112749010379997186", // IDA_V2_WORKER
};
const ASYNC_IDA_ENABLED = true;
// with COMPLETE_POST off, a big Complete & Post completes in the background (COMPLETE on) and is posted from the list
const IDA_V2_ACTIONS = { COMPLETE: true, COMPLETE_POST: false };
// rollback = bind the button back to this classic handler
const IDA_CLASSIC = "onClick_saveAsCompleted";
const IDA_BUTTON_POSTS = false;
const IDA_POLL_MS = 2500;
const IDA_KICK_MS = 15000;
const IDA_WAIT_MS = 420000;
const IDA_LINK_POLL_MS = 3000;
const IDA_LINK_WAIT_MS = 90000;
const IDA_KICK_MAX = 10;
const IDA_RUNNING = ["QUEUED", "VALIDATING", "READY_TO_COMMIT", "COMMITTING_IDA"];
const IDA_TERMINAL = ["COMPLETED", "FAILED", "REQUIRES_REVIEW", "CANCELLED"];
// not record fields (every dialog_* key too): the job's fields, the stock dialog, buttons, badges, layout, platform keys
const IDA_NOT_RECORD = ["ida_v2_job_id", "ida_idem_key", "_data", "$_v", "_vts", "isTrusted", "sm_item_balance", "button_draft",
  "button_completed", "comp_post_button", "button_post", "button_kdsxzl2q", "draft_status", "issued_status", "completed_status",
  "fullyposted_status", "processing_status", "flex_2det1nd2", "flex_t6y2yh5r", "ida_source_stock_mode", "item_display_table"];

// client copies of code/shared/ida_common.js (CONTRACT section 6); test_json_integrity.js keeps them identical
const idaS = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const idaParseJ = (t) => {
  if (t === undefined || t === null) return null;
  if (typeof t === "object") return t;
  try {
    return JSON.parse(String(t).replace(/"(?:[^"\\]|\\.)*"|(^\s*|[:\[,]\s*)(-?\d{16,})(?=\s*(?:[,\]}]|$))/g, (m, pre, num) => (num === undefined ? m : pre + '"' + num + '"')));
  } catch (e) {
    return null;
  }
};
const idaList = (x) => (Array.isArray(x) ? x : x ? [x] : []).filter((r) => r !== undefined && r !== null);
const idaJsonList = (v) => {
  if (Array.isArray(v)) return v;
  const t = idaS(v);
  if (!t) return [];
  const p = idaParseJ(t);
  return Array.isArray(p) ? p : [];
};
const idaPicks = (header) => idaJsonList(header && header.temp_qty_data).filter((p) => p && typeof p === "object" && (parseFloat(p.sm_quantity) || 0) > 0);
const idaPickCount = (header) => idaPicks(header).length;
const idaRecoveryLines = (lines) => idaList(lines).filter((l) => l && typeof l === "object" && idaS(l.item_selection) !== "");
const idaMoveCount = (header, lines) => idaPickCount(header) + idaRecoveryLines(lines).length;
const idaHasHu = (header) => {
  const h = header || {};
  return idaJsonList(h.temp_qty_data).some((p) => p && typeof p === "object" && idaS(p.handling_unit_id) !== "")
    || idaJsonList(h.temp_hu_data).length > 0 || idaJsonList(h.table_hu).length > 0;
};
const idaPickHasSerial = (header) => idaJsonList(header && header.temp_qty_data).some((p) => p && typeof p === "object" && idaS(p.serial_number) !== "");
const IDA_V2_MIN_MOVES = 50;
const IDA_TEXT = {
  busy: "This Item Disassembly is being processed in the background - please wait for it to finish.",
  queueFailed: "The completion could not be queued: please try again.",
  postLater: "Still completing in the background; post it from the list once it shows Completed.",
};

const idaOn = () => ASYNC_IDA_ENABLED === true && [IDA_WF.SUBMIT, IDA_WF.WORKER].every((id) => /^[1-9][0-9]{0,19}$/.test(id));
// COMPLETE for the Completed button; COMPLETE_POST (or, when it is off, COMPLETE) for Complete & Post
const modeOf = () => {
  if (!IDA_BUTTON_POSTS) return IDA_V2_ACTIONS.COMPLETE === true ? "COMPLETE" : "";
  if (IDA_V2_ACTIONS.COMPLETE_POST === true) return "POST";
  return IDA_V2_ACTIONS.COMPLETE === true ? "POST_LATER" : "";
};

const digits = (v) => /^[0-9]{1,20}$/.test(idaS(v));
// SUBMIT answers "" (or "0") until the job is linked to the disassembly it saved
const linked = (v) => /^[1-9][0-9]{0,19}$/.test(idaS(v));
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

const data_ = () => this.models["_data"] || {};
const store = (patch) => {
  this.models["_data"] = { ...this.models["_data"], ...patch };
};

const release = () => {
  store({ ida_submitting: 0 });
  this.hideLoading();
};

const closeDialog = () => {
  if (this.parentGenerateForm) {
    this.parentGenerateForm.$refs.SuPageDialogRef.hide();
    this.parentGenerateForm.refresh();
  }
};

const refreshList = () => {
  if (this.parentGenerateForm) this.parentGenerateForm.refresh();
};

// settles on the callback or on the promise runWorkflow returns, whichever comes first
const run = (id, params) =>
  new Promise((resolve, reject) => {
    const p = this.runWorkflow(id, params, (res) => resolve(res), (err) => reject(err));
    if (p && typeof p.then === "function") p.then((res) => resolve(res), (err) => reject(err));
  });

// an alert closed with its X rejects: it was still read
const alertBox = (message, title, type) =>
  this.$alert(message, title || "", { confirmButtonText: "OK", type: type, dangerouslyUseHTMLString: false }).catch(() => {});

const markSeen = (jobId) => {
